import java.io.*;

public class Main {
    // Return a map from each distinct string to its count, in order of first appearance.
    static LinkedHashMap<String, Integer> countStrings(String[] words) {
        // Write your solution here
        return new LinkedHashMap<>();
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        String[] words = new String[n];
        for (int i = 0; i < n; i++) words[i] = st.nextToken();
        LinkedHashMap<String, Integer> counts = countStrings(words);
        StringBuilder sb = new StringBuilder();
        sb.append(String.join(" ", counts.keySet())).append('\n');
        for (Map.Entry<String, Integer> e : counts.entrySet()) sb.append(e.getKey()).append(' ').append(e.getValue()).append('\n');
        System.out.print(sb);
    }
}

