def gen(rng):
    def fmt(ws):
        return str(len(ws)) + '\n' + ' '.join(ws)
    def rw(alpha, lo, hi):
        return ''.join(rng.choice(alpha) for _ in range(rng.randint(lo, hi)))
    tests = [fmt(['a']), fmt(['a', 'a']), fmt(['a', 'A', 'a']), fmt(['x', 'y', 'z']),
             fmt(['same'] * 7), fmt(['b', 'a', 'b', 'a', 'c'])]
    for n in (3, 5, 8, 12, 20, 30):
        for _ in range(3):
            pool = [rw('abc', 1, 3) for _ in range(rng.randint(1, 8))]
            tests.append(fmt([rng.choice(pool) for _ in range(n)]))
    letters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    tests.append(fmt([rw(letters, 1, 10) for _ in range(100000)]))
    pool = [rw(letters, 1, 10) for _ in range(50)]
    tests.append(fmt([rng.choice(pool) for _ in range(100000)]))
    tests.append(fmt(['abcdefghij'] * 100000))
